// src/index.js
import './App.scss';
import './Button.scss';
import './Responsive1500.scss';
import React from "react";
import ReactDOM from "react-dom/client";
import App from "./App";
import { worker } from "./mocks/browser";
import { FRONT_BASE } from './api/config';

// MSW 먼저 준비시키고, 준비된 뒤에 React 렌더
(async function bootstrap() {
  const base = (FRONT_BASE || "/").replace(/\/+$/,""); // 끝 슬래시 제거
  const url  = `${base}/mockServiceWorker.js`;
  const scope = `${base}/`;
  await worker.start({
    serviceWorker: { url, options: { scope } },
    onUnhandledRequest: "bypass",
  });
  console.log("[MSW] registered:", { url, scope });

  const root = ReactDOM.createRoot(document.getElementById("root"));
  root.render(
    <React.StrictMode>
      <App />
    </React.StrictMode>
  );
})();
